#!/usr/bin/env bash
# Deploy the site (docs/: pages, scripts and the published data) to the
# gh-pages branch as ONE fresh commit that replaces whatever was there.
#
# The published data (docs/data, ~1 MB per run) is regenerated by publish.py
# and never committed to main, so the repository does not grow with every
# publish: gh-pages always holds exactly one snapshot, force-pushed.
#
# One-time setup: GitHub -> Settings -> Pages -> "Deploy from a branch",
# branch gh-pages, folder / (root).
#
# Usage (from anywhere in the repo, after orbit_planning/publish.py):
#   scripts/deploy_site.sh
#   REMOTE=upstream BRANCH=gh-pages scripts/deploy_site.sh
#   DRY_RUN=1 scripts/deploy_site.sh      # build the commit, do not push
set -euo pipefail

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
REMOTE="${REMOTE:-origin}"
BRANCH="${BRANCH:-gh-pages}"
DRY_RUN="${DRY_RUN:-0}"

if [[ ! -f "$ROOT/docs/data/index.json" ]]; then
  echo "no docs/data/index.json: run orbit_planning/publish.py first" >&2
  exit 1
fi

# Build the snapshot in a scratch work tree, committing straight into this
# repository's object store (so the push below uses this repo's remotes and
# credentials), on a temporary ref that is removed afterwards.
STAGE="$(mktemp -d)"
TMP_INDEX="$(mktemp)"
TMP_REF="refs/heads/_site_deploy_$$"
cleanup() { rm -rf "$STAGE" "$TMP_INDEX"; git -C "$ROOT" update-ref -d "$TMP_REF" 2>/dev/null || true; }
trap cleanup EXIT

cp -R "$ROOT/docs/." "$STAGE/"
touch "$STAGE/.nojekyll"          # serve files as-is, no Jekyll build
find "$STAGE" -name '.DS_Store' -delete

export GIT_INDEX_FILE="$TMP_INDEX"
export GIT_WORK_TREE="$STAGE"
export GIT_DIR="$(git -C "$ROOT" rev-parse --git-dir)"
case "$GIT_DIR" in /*) ;; *) GIT_DIR="$ROOT/$GIT_DIR" ;; esac
rm -f "$TMP_INDEX"
cd "$STAGE"
git add -A -f .
TREE="$(git write-tree)"
SRC="$(git -C "$ROOT" rev-parse --short HEAD)"
COMMIT="$(git commit-tree "$TREE" -m "Site snapshot from ${SRC} ($(date -u +%Y-%m-%dT%H:%MZ))")"
git update-ref "$TMP_REF" "$COMMIT"
unset GIT_INDEX_FILE GIT_WORK_TREE GIT_DIR
cd "$ROOT"

SIZE="$(du -sh "$STAGE" | cut -f1)"
RUNS="$(find "$STAGE/data" -name cloud.json | wc -l | tr -d ' ')"
echo "snapshot ${COMMIT:0:10}: ${RUNS} runs, ${SIZE} (site code from ${SRC})"
if [[ "$DRY_RUN" == 1 ]]; then
  echo "DRY_RUN=1: not pushing"
  exit 0
fi
git -C "$ROOT" push --force "$REMOTE" "$TMP_REF:refs/heads/$BRANCH"
echo "deployed to $REMOTE/$BRANCH; GitHub Pages republishes it within a minute or two"
